type ProgramStatsRow struct {
	ChallengeID  uint64
	Participants int64
	Completed    int64
}

// ---------------------------------------------------------------------------
// Admin stats
// Participants / completions per v2 challenge (the list columns).
func (q *Queries) ProgramStats(ctx context.Context, ids []uint64) ([]ProgramStatsRow, error) {
	query := programStats
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProgramStatsRow{}
	for rows.Next() {
		var i ProgramStatsRow
		if err := rows.Scan(&i.ChallengeID, &i.Participants, &i.Completed); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

