const upsertProgram = `-- name: UpsertProgram :exec
INSERT INTO ` + "`" + `challenge_programs` + "`" + ` (challenge_id, duration_days, start_rule, starts_on, reminder_time, eligibility,
                                  reward_badge_code, reward_badge_title, reward_plus_days, completion_min_days,
                                  created_at, updated_at)
VALUES (?, ?, ?, ?,
        ?, ?, ?,
        ?, ?, ?,
        ?, ?)
ON DUPLICATE KEY UPDATE duration_days = VALUES(duration_days), start_rule = VALUES(start_rule),
  starts_on = VALUES(starts_on), reminder_time = VALUES(reminder_time), eligibility = VALUES(eligibility),
  reward_badge_code = VALUES(reward_badge_code), reward_badge_title = VALUES(reward_badge_title),
  reward_plus_days = VALUES(reward_plus_days), completion_min_days = VALUES(completion_min_days),
  updated_at = VALUES(updated_at)
`

type UpsertProgramParams struct {
	ChallengeID       uint64
	DurationDays      uint16
	StartRule         string
	StartsOn          civildate.NullDate
	ReminderTime      sql.NullString
	Eligibility       db.NullRawJSON
	RewardBadgeCode   sql.NullString
	RewardBadgeTitle  db.NullRawJSON
	RewardPlusDays    uint16
	CompletionMinDays sql.NullInt16
	Now               sql.NullTime
}

func (q *Queries) UpsertProgram(ctx context.Context, arg UpsertProgramParams) error {
	_, err := q.db.ExecContext(ctx, upsertProgram,
		arg.ChallengeID,
		arg.DurationDays,
		arg.StartRule,
		arg.StartsOn,
		arg.ReminderTime,
		arg.Eligibility,
		arg.RewardBadgeCode,
		arg.RewardBadgeTitle,
		arg.RewardPlusDays,
		arg.CompletionMinDays,
		arg.Now,
		arg.Now,
	)
	return err
}
